def mk(base, supports):
    d = dict(base)
    d["supports"] = supports
    if "citation" not in d:
        d["citation"] = "%s (%d). %s. %s." % (d["authors"], d["year"], d["title_en"], d["publisher"])
    d.setdefault("locator", "book")
    d.setdefault("locator_type", "BOOK")
    d.setdefault("verified", True)
    return d


